import getIssueTool from "./get-issue.js";

describe("get_issue issue links", () => {
  const ENV_KEYS = [
    "ATLASSIAN_CLOUD_ID",
    "ATLASSIAN_EMAIL",
    "ATLASSIAN_JIRA_READ_ONLY_TOKEN",
  ] as const;
  const saved: Record<string, string | undefined> = {};
  const blocksType = {
    name: "Blocks",
    inward: "is blocked by",
    outward: "blocks",
  };

  const mockIssue = (fields: Record<string, unknown>) =>
    mockGet.mockResolvedValueOnce({
      data: { key: "PM-1", fields: { summary: "Issue", ...fields } },
    });

  beforeEach(() => {
    vi.clearAllMocks();
    for (const key of ENV_KEYS) {
      saved[key] = process.env[key];
    }
    process.env.ATLASSIAN_CLOUD_ID = "test-cloud-id";
    process.env.ATLASSIAN_EMAIL = "user@example.com";
    process.env.ATLASSIAN_JIRA_READ_ONLY_TOKEN = "read-token";
  });

  afterEach(() => {
    for (const key of ENV_KEYS) {
      if (saved[key] === undefined) {
        delete process.env[key];
      } else {
        process.env[key] = saved[key];
      }
    }
  });

  it("renders an outward link with the outward phrase", async () => {
    mockIssue({
      issuelinks: [
        {
          type: blocksType,
          outwardIssue: {
            key: "PM-2",
            fields: { summary: "Blocked work", status: { name: "To Do" } },
          },
        },
      ],
    });

    const out = await getIssueTool.handler({ issueIdOrKey: "PM-1" });

    expect(out).toContain("## Issue Links");
    expect(out).toContain("- blocks **[PM-2]** Blocked work - To Do");
  });

  it("renders an inward link with the inward phrase", async () => {
    mockIssue({
      issuelinks: [
        {
          type: blocksType,
          inwardIssue: {
            key: "PM-3",
            fields: { summary: "Blocker", status: { name: "In Progress" } },
          },
        },
      ],
    });

    const out = await getIssueTool.handler({ issueIdOrKey: "PM-1" });

    expect(out).toContain("- is blocked by **[PM-3]** Blocker - In Progress");
  });

  it("renders no section when issuelinks is empty", async () => {
    mockIssue({ issuelinks: [] });

    const out = await getIssueTool.handler({ issueIdOrKey: "PM-1" });

    expect(out).not.toContain("## Issue Links");
  });

  it("renders no section when issuelinks is missing", async () => {
    mockIssue({});

    const out = await getIssueTool.handler({ issueIdOrKey: "PM-1" });

    expect(out).not.toContain("## Issue Links");
  });

  it("falls back to No summary and Unknown for a sparse linked issue", async () => {
    mockIssue({
      issuelinks: [{ type: blocksType, outwardIssue: { key: "PM-2" } }],
    });

    const out = await getIssueTool.handler({ issueIdOrKey: "PM-1" });

    expect(out).toContain("- blocks **[PM-2]** No summary - Unknown");
  });

  it("renders the links when only the issuelinks field is requested", async () => {
    mockIssue({
      issuelinks: [
        {
          type: blocksType,
          inwardIssue: {
            key: "PM-3",
            fields: { summary: "Blocker", status: { name: "Done" } },
          },
        },
      ],
    });

    const out = await getIssueTool.handler({
      issueIdOrKey: "PM-1",
      fields: ["issuelinks"],
    });

    expect(mockGet).toHaveBeenCalledWith(
      "/rest/api/3/issue/PM-1",
      expect.objectContaining({
        params: expect.objectContaining({ fields: "issuelinks" }),
      }),
    );
    expect(out).toContain("- is blocked by **[PM-3]** Blocker - Done");
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";

/**
 * Tests for ConfluenceClient error handling.
 *
 * We extract the error interceptor registered during construction
 * and exercise handleError indirectly.
 */

const mockAxiosInstance: any = {
  get: vi.fn(),
  interceptors: {
    response: { use: vi.fn() },
  },
};

vi.mock("axios", () => ({
  default: {
    create: vi.fn(() => mockAxiosInstance),
  },
}));

vi.mock("./auth.js", () => ({
  loadConfluenceConfig: () => ({
    cloudId: "test-cloud-id",
    gatewayBaseUrl: "https://api.atlassian.com/ex/confluence/test-cloud-id",
    email: "user@example.com",
    apiToken: "test-token",
  }),
  getConfluenceHeaders: () => ({
    Authorization: "Basic dGVzdA==",
    Accept: "application/json",
    "Content-Type": "application/json",
  }),
}));

import { ConfluenceClient } from "./client.js";

describe("ConfluenceClient error handling", () => {
  let handleError: (error: any) => any;

  beforeEach(() => {
    vi.clearAllMocks();
    new ConfluenceClient();
    // Extract the rejection handler registered on interceptors.response.use
    const calls = mockAxiosInstance.interceptors.response.use.mock.calls;
    const errorHandler = calls[calls.length - 1][1];
    // handleError returns Promise.reject(err), so we unwrap
    handleError = async (error: any) => {
      try {
        await errorHandler(error);
      } catch (e) {
        return e;
      }
    };
  });

  it("should map 401 to authentication failed", async () => {
    const err = await handleError({
      response: { status: 401, data: {} },
      config: {},
    });
    expect(err.message).toContain("authentication failed");
  });

  it("should map 403 to access forbidden", async () => {
    const err = await handleError({
      response: { status: 403, data: {} },
      config: {},
    });
    expect(err.message).toContain("access forbidden");
  });

  it("should map 404 to resource not found with URL", async () => {
    const err = await handleError({
      response: { status: 404, data: {} },
      config: { url: "/wiki/api/v2/pages/123" },
    });
    expect(err.message).toContain("resource not found");
    expect(err.message).toContain("/wiki/api/v2/pages/123");
  });

  it("should map 429 to rate limit", async () => {
    const err = await handleError({
      response: { status: 429, data: {} },
      config: {},
    });
    expect(err.message).toContain("rate limit");
  });

  it("should map 500 with data.message", async () => {
    const err = await handleError({
      response: { status: 500, data: { message: "Internal failure" } },
      config: {},
      message: "Request failed",
    });
    expect(err.message).toContain("API error (500)");
    expect(err.message).toContain("Internal failure");
  });

  it("should map 500 without data.message to error.message", async () => {
    const err = await handleError({
      response: { status: 500, data: {} },
      config: {},
      message: "Request failed with status 500",
    });
    expect(err.message).toContain("API error (500)");
    expect(err.message).toContain("Request failed with status 500");
  });

  it("should handle no response with request present", async () => {
    const err = await handleError({
      request: {},
      message: "Network Error",
      config: {},
    });
    expect(err.message).toContain("request failed");
    expect(err.message).toContain("ATLASSIAN_CLOUD_ID");
  });

  it("should handle no response and no request", async () => {
    const err = await handleError({
      message: "Something went wrong",
      config: {},
    });
    expect(err.message).toContain("client error");
  });
});

import { describe, it, expect } from "vitest";

import { buildDescriptionAdf, buildCommentAdf } from "./adf-build.js";

describe("buildDescriptionAdf", () => {
  it("builds one ADF paragraph per input string", () => {
    const doc = buildDescriptionAdf(["First para.", "Second para."]);

    expect(doc).toEqual({
      version: 1,
      type: "doc",
      content: [
        { type: "paragraph", content: [{ type: "text", text: "First para." }] },
        {
          type: "paragraph",
          content: [{ type: "text", text: "Second para." }],
        },
      ],
    });
  });

  it("trims surrounding whitespace", () => {
    const doc = buildDescriptionAdf(["  padded  "]);

    expect(doc?.content[0].content[0].text).toBe("padded");
  });

  it("drops empty and whitespace-only paragraphs", () => {
    const doc = buildDescriptionAdf(["kept", "   ", ""]);

    expect(doc?.content).toHaveLength(1);
  });

  it("returns undefined when there is nothing to send", () => {
    expect(buildDescriptionAdf([])).toBeUndefined();
    expect(buildDescriptionAdf(["  ", ""])).toBeUndefined();
  });
});

describe("buildCommentAdf", () => {
  it("builds a single paragraph for text with no blank lines", () => {
    const doc = buildCommentAdf("Looks good to me.");

    expect(doc).toEqual({
      version: 1,
      type: "doc",
      content: [
        {
          type: "paragraph",
          content: [{ type: "text", text: "Looks good to me." }],
        },
      ],
    });
  });

  it("splits on blank lines into separate paragraphs", () => {
    const doc = buildCommentAdf("First paragraph.\n\nSecond paragraph.");

    expect(doc.content).toEqual([
      {
        type: "paragraph",
        content: [{ type: "text", text: "First paragraph." }],
      },
      {
        type: "paragraph",
        content: [{ type: "text", text: "Second paragraph." }],
      },
    ]);
  });

  it("treats blank lines with trailing whitespace as paragraph breaks", () => {
    const doc = buildCommentAdf("First.\n  \nSecond.\n\n\nThird.");

    expect(doc.content).toEqual([
      { type: "paragraph", content: [{ type: "text", text: "First." }] },
      { type: "paragraph", content: [{ type: "text", text: "Second." }] },
      { type: "paragraph", content: [{ type: "text", text: "Third." }] },
    ]);
  });
});
